import { app, page, route, query, action, api, apiNamespace } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { FolderPage } from "./src/FolderPage" with { type: "ref" };
import { LogsPage } from "./src/LogsPage" with { type: "ref" };
import { SharePage } from "./src/SharePage" with { type: "ref" };
import { LoginPage, SignupPage } from "./src/AuthPage" with { type: "ref" };

import { getRunId, getFolder, getRootContents, getAccessLogs } from "./src/queries" with { type: "ref" };
import { createFolder, createShareLink } from "./src/actions" with { type: "ref" };
import { configureFileUploadMiddleware, uploadFile, downloadFile } from "./src/apis" with { type: "ref" };

export default app({
  name: "app",
  wasp: { version: "^0.25.0" },
  title: "Wasp File Management",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("FolderRoute", "/folder/:folderId", page(FolderPage, { authRequired: true })),
    route("LogsRoute", "/logs", page(LogsPage, { authRequired: true })),
    route("ShareRoute", "/share/:linkId", page(SharePage, { authRequired: false })),
    route("SignupRoute", "/signup", page(SignupPage)),
    route("LoginRoute", "/login", page(LoginPage)),

    query(getRunId),
    query(getFolder, { entities: ["Folder", "File"] }),
    query(getRootContents, { entities: ["Folder", "File"] }),
    query(getAccessLogs, { entities: ["AccessLog", "ShareLink", "File"] }),

    action(createFolder, { entities: ["Folder"] }),
    action(createShareLink, { entities: ["ShareLink", "File"] }),

    apiNamespace("/api/upload", { middlewareConfigFn: configureFileUploadMiddleware }),
    api("POST", "/api/upload", uploadFile, { entities: ["File"] }),
    api("GET", "/api/download/:linkId", downloadFile, { entities: ["ShareLink", "AccessLog"] }),
  ],
});

import fs from "fs";
import { HttpError } from "wasp/server";
import type { GetRunId, GetFolder, GetRootContents, GetAccessLogs } from "wasp/server/operations";

export const getRunId: GetRunId<void, string> = async () => {
  try {
    const runId = fs.readFileSync("/logs/artifacts/run-id", "utf-8").trim();
    return runId;
  } catch (error) {
    console.error("Error reading run-id file:", error);
    return "unknown";
  }
};

export const getFolder: GetFolder<{ folderId: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const folder = await context.entities.Folder.findFirst({
    where: {
      id: args.folderId,
      userId: context.user.id,
    },
  });

  if (!folder) {
    throw new HttpError(404, "Folder not found");
  }

  // Build the breadcrumb path
  const path: any[] = [];
  let current = folder;
  while (current.parentId !== null) {
    const parent = await context.entities.Folder.findUnique({
      where: { id: current.parentId },
    });
    if (parent) {
      path.unshift(parent);
      current = parent;
    } else {
      break;
    }
  }

  const subfolders = await context.entities.Folder.findMany({
    where: {
      parentId: args.folderId,
      userId: context.user.id,
    },
    orderBy: {
      name: "asc",
    },
  });

  const files = await context.entities.File.findMany({
    where: {
      folderId: args.folderId,
      userId: context.user.id,
    },
    include: {
      shareLinks: true,
    },
    orderBy: {
      name: "asc",
    },
  });

  return {
    folder,
    path,
    subfolders,
    files,
  };
};

export const getRootContents: GetRootContents<void, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const subfolders = await context.entities.Folder.findMany({
    where: {
      parentId: null,
      userId: context.user.id,
    },
    orderBy: {
      name: "asc",
    },
  });

  const files = await context.entities.File.findMany({
    where: {
      folderId: null,
      userId: context.user.id,
    },
    include: {
      shareLinks: true,
    },
    orderBy: {
      name: "asc",
    },
  });

  return {
    subfolders,
    files,
  };
};

export const getAccessLogs: GetAccessLogs<void, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  return context.entities.AccessLog.findMany({
    where: {
      shareLink: {
        file: {
          userId: context.user.id,
        },
      },
    },
    orderBy: {
      timestamp: "desc",
    },
  });
};

import fs from "fs";
import { HttpError } from "wasp/server";
import type { CreateFolder, CreateShareLink } from "wasp/server/operations";

let runIdCache = "";
const getRunIdInternal = (): string => {
  if (runIdCache) return runIdCache;
  try {
    runIdCache = fs.readFileSync("/logs/artifacts/run-id", "utf-8").trim();
    return runIdCache;
  } catch (error) {
    console.error("Error reading run-id file:", error);
    return "unknown";
  }
};

export const createFolder: CreateFolder<
  { name: string; parentId: number | null },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const runId = getRunIdInternal();
  const suffix = `-${runId}`;
  let folderName = args.name;
  if (!folderName.endsWith(suffix)) {
    folderName = `${folderName}${suffix}`;
  }

  return context.entities.Folder.create({
    data: {
      name: folderName,
      parentId: args.parentId,
      userId: context.user.id,
    },
  });
};

export const createShareLink: CreateShareLink<
  { fileId: number; password?: string; expiresInMinutes?: number },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const file = await context.entities.File.findFirst({
    where: {
      id: args.fileId,
      userId: context.user.id,
    },
  });

  if (!file) {
    throw new HttpError(404, "File not found");
  }

  let expiresAt: Date | null = null;
  if (args.expiresInMinutes && args.expiresInMinutes > 0) {
    expiresAt = new Date(Date.now() + args.expiresInMinutes * 60 * 1000);
  }

  const password = args.password && args.password.trim() !== "" ? args.password.trim() : null;

  return context.entities.ShareLink.create({
    data: {
      fileId: args.fileId,
      password,
      expiresAt,
    },
  });
};

import fs from "fs";
import path from "path";
import multer from "multer";
import type { MiddlewareConfigFn } from "wasp/server";
import type { UploadFile, DownloadFile } from "wasp/server/api";

const uploadDir = "/home/user/app/uploads/";
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
    cb(null, uniqueSuffix + "-" + file.originalname);
  },
});

const upload = multer({ storage });

export const configureFileUploadMiddleware: MiddlewareConfigFn = (config) => {
  config.set("multer", upload.single("file"));
  return config;
};

export const uploadFile: UploadFile = async (req, res, context) => {
  if (!context.user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const file = req.file;
  if (!file) {
    return res.status(400).json({ error: "No file uploaded" });
  }

  const folderIdStr = req.body.folderId;
  const folderId =
    folderIdStr && folderIdStr !== "null" && folderIdStr !== "undefined"
      ? parseInt(folderIdStr, 10)
      : null;

  try {
    const newFile = await context.entities.File.create({
      data: {
        name: file.originalname,
        path: file.path,
        mimeType: file.mimetype,
        size: file.size,
        folderId,
        userId: context.user.id,
      },
    });

    return res.json({ success: true, file: newFile });
  } catch (error: any) {
    console.error("Error creating file metadata:", error);
    return res.status(500).json({ error: error.message });
  }
};

export const downloadFile: DownloadFile = async (req, res, context) => {
  const { linkId } = req.params;

  try {
    const shareLink = await context.entities.ShareLink.findUnique({
      where: { id: linkId },
      include: {
        file: true,
      },
    });

    if (!shareLink) {
      return res.status(404).json({ error: "Share link not found" });
    }

    // Check expiration
    if (shareLink.expiresAt && new Date() > new Date(shareLink.expiresAt)) {
      return res.status(410).json({ error: "Link has expired" });
    }

    // Check password
    if (shareLink.password) {
      const providedPassword = req.query.password;
      if (!providedPassword || providedPassword !== shareLink.password) {
        return res.status(403).json({ error: "Invalid password" });
      }
    }

    const filePath = shareLink.file.path;
    if (!fs.existsSync(filePath)) {
      return res.status(404).json({ error: "File content not found on server" });
    }

    // Record Access Log
    const ipAddress = (req.headers["x-forwarded-for"] || req.socket.remoteAddress || "unknown") as string;
    const userAgent = (req.headers["user-agent"] || "unknown") as string;

    await context.entities.AccessLog.create({
      data: {
        shareLinkId: shareLink.id,
        ipAddress,
        userAgent,
        fileName: shareLink.file.name,
      },
    });

    // Serve file
    res.setHeader("Content-Type", shareLink.file.mimeType);
    res.setHeader("Content-Disposition", `attachment; filename="${encodeURIComponent(shareLink.file.name)}"`);

    const fileStream = fs.createReadStream(filePath);
    fileStream.pipe(res);
  } catch (error: any) {
    console.error("Error downloading file:", error);
    return res.status(500).json({ error: error.message });
  }
};

